@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-progress-ring {
    --_nz-progress-ring-size: 4.5rem;
    --_nz-progress-ring-fill: var(--nz-chart-primary);

    display: inline-grid;
    place-items: center;
    inline-size: var(--nz-progress-ring-size, var(--_nz-progress-ring-size));
    block-size: var(--nz-progress-ring-size, var(--_nz-progress-ring-size));
    color: var(--nz-text-primary);
  }

  /* the svg and the label share one cell, so the label sits in the centre */
  .nz-progress-ring-svg,
  .nz-progress-ring-label {
    grid-area: 1 / 1;
  }

  .nz-progress-ring-svg {
    inline-size: 100%;
    block-size: 100%;
  }

  .nz-progress-ring-track {
    stroke: var(--nz-progress-ring-track-bg, var(--nz-chart-track));
  }

  .nz-progress-ring-fill {
    stroke: var(--nz-progress-ring-fill, var(--_nz-progress-ring-fill));
    stroke-linecap: butt;
    transition: stroke-dasharray var(--nz-duration-base) var(--nz-easing-standard);
  }

  .nz-progress-ring-label {
    font: var(--nz-progress-ring-label-font, var(--nz-font-label-m-strong));
    font-variant-numeric: tabular-nums;
    unicode-bidi: isolate;
  }

  .nz-progress-ring[data-size='sm'] {
    --_nz-progress-ring-size: 3rem;
  }

  .nz-progress-ring[data-size='lg'] {
    --_nz-progress-ring-size: 6rem;
  }

  .nz-progress-ring[data-tone='success'] {
    --_nz-progress-ring-fill: var(--nz-chart-success);
  }

  .nz-progress-ring[data-tone='warning'] {
    --_nz-progress-ring-fill: var(--nz-chart-warning);
  }

  .nz-progress-ring[data-tone='critical'] {
    --_nz-progress-ring-fill: var(--nz-chart-critical);
  }

  /* chart/neutral (neutral 500 / 400 since the 2026-10-18 sync, the colours icon/secondary drew
     before) reaches 3:1 on chart/track in both themes (1.4.11) */
  .nz-progress-ring[data-tone='neutral'] {
    --_nz-progress-ring-fill: var(--nz-chart-neutral);
  }

  /* fill and stroke are forced too, which would merge the track and the arc: keep two system colours */
  @media (forced-colors: active) {
    .nz-progress-ring-svg {
      forced-color-adjust: none;
    }

    .nz-progress-ring-track {
      stroke: GrayText;
    }

    .nz-progress-ring-fill {
      stroke: Highlight;
    }
  }

  /* Optical centring (M85, as Button's label): trimmed to cap height and baseline, padded back to
     one line, so the box keeps its height and the letters sit in its middle. */
  @supports (text-box: trim-both cap alphabetic) {
    .nz-progress-ring-label {
      padding-block: calc((1lh - 1cap) / 2);
      text-box: trim-both cap alphabetic;
    }
  }
}
